/// Run `convert` with configured options-field bridge support.
///
/// Returns an owned `ConversionResult` handle on success, or zero on failure. Check
/// `htm_last_error_code` / `htm_last_error_context` for error details. Free
/// the returned handle with `htm_conversion_result_free`.
///
/// If a bridge was attached to `options`, it is cloned into the core call.
///
/// # Safety
///
/// String pointers must be valid and NUL-terminated for the duration of this call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn htm_convert(html: *const std::ffi::c_char, options: AlefHandle) -> AlefHandle {
    catch_ffi_panic(0, || {
        clear_last_error();

        if html.is_null() {
            set_last_error(1, "Null pointer passed for html");
            return 0;
        }

        // SAFETY: null check above guarantees html is a valid pointer.
        let html_rs = match unsafe { std::ffi::CStr::from_ptr(html) }.to_str() {
            Ok(s) => s,
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in html parameter");
                return 0;
            }
        };

        let options_rs: Option<html_to_markdown_rs::ConversionOptions> = if options == 0 {
            None
        } else {
            match with_handle::<html_to_markdown_rs::ConversionOptions, _>(options, Clone::clone) {
                Ok(options) => Some(options),
                Err(error) => {
                    set_handle_error(&error);
                    return 0;
                }
            }
        };

        match html_to_markdown_rs::convert(html_rs, options_rs) {
            Ok(result) => match insert_handle(result) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(error) => {
                set_last_error_from(&error, &error.to_string());
                0
            }
        }
    })
}

/// Attach a vtable visitor bridge to a `ConversionOptions` options handle.
///
/// The `HtmVisitor` encapsulates C callbacks invoked during conversion. Neither handle
/// is consumed; both must be freed independently after every conversion using the options
/// handle has completed. Pass `visitor = 0` to clear a previously attached visitor.
///
/// # Safety
