/// Create a new visitor handle from a callbacks struct.
///
/// The returned handle must be freed with `htm_visitor_free`.
/// The `HtmVisitorCallbacks` struct is **copied** into the handle;
/// the caller may free it after this call returns.
///
/// Returns null on allocation failure.
///
/// # Safety
///
/// `callbacks` must point to a valid, fully initialised `HtmVisitorCallbacks`.
/// `user_data` (embedded in the struct) must remain valid and accessible from
/// any thread that calls `htm_convert_with_visitor` until after
/// `htm_visitor_free` is called.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn htm_visitor_create(callbacks: *const HtmVisitorCallbacks) -> AlefHandle {
    catch_ffi_panic(0, || {
        if callbacks.is_null() {
            return 0;
        }
        // SAFETY: caller guarantees the pointer is valid.
        let cbs = unsafe { callbacks.read() };
        let visitor = HtmVisitor {
            callbacks: cbs,
            _tag_scratch: std::cell::RefCell::new(Vec::new()),
        };
        match insert_handle(visitor) {
            Ok(handle) => handle,
            Err(error) => {
                set_handle_error(&error);
                0
            }
        }
    })
}

/// Free a visitor handle previously returned by `htm_visitor_create`.
///
/// After this call the pointer is invalid and must not be used.
///
/// # Safety
///
/// `visitor` must have been returned by `htm_visitor_create`, or be null.
/// Passing a null pointer is safe and has no effect.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn htm_visitor_free(visitor: AlefHandle) {
    catch_ffi_panic((), || {
        if visitor != 0
            && let Err(error) = remove_handle::<HtmVisitor>(visitor)
        {
            set_handle_error(&error);
        }
    })
}

/// Write an error message string into an FFI out-error pointer.
///
/// # Safety
///
/// `out_error` must be null or a valid writable `*mut *mut c_char` pointer.
unsafe fn ffi_set_out_error(out_error: *mut *mut std::ffi::c_char, msg: &str) {
    if !out_error.is_null()
        && let Ok(cs) = std::ffi::CString::new(msg)
    {
        // SAFETY: out_error is non-null; caller must free this string.
        unsafe {
            *out_error = cs.into_raw();
        }
    }
}
